package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	// dp[i][j] = minimum weight to triangulate polygon vertices i..j (inclusive)
	// vertices are labeled 1..n
	// We use 1-based indexing for dp
	const INF = 1 << 60
	dp := make([][]int64, n+1)
	for i := range dp {
		dp[i] = make([]int64, n+1)
		for j := range dp[i] {
			dp[i][j] = INF
		}
	}

	// Base case: segments of length 1 or 2 (no triangle possible)
	for i := 1; i <= n; i++ {
		dp[i][i] = 0
		if i+1 <= n {
			dp[i][i+1] = 0
		}
	}

	// Fill dp for increasing lengths of vertex sequences
	for length := 3; length <= n; length++ {
		for i := 1; i+length-1 <= n; i++ {
			j := i + length - 1
			for k := i + 1; k < j; k++ {
				// Triangle (i, k, j)
				triangleWeight := int64(i * k * j)
				total := dp[i][k] + dp[k][j] + triangleWeight
				if total < dp[i][j] {
					dp[i][j] = total
				}
			}
		}
	}

	fmt.Println(dp[1][n])
}
