package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n int
	fmt.Fscan(reader, &n)

	if n == 3 {
		fmt.Fprintln(writer, 6)
		return
	}

	// Initialize DP table
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
	}

	// Fill DP table for all lengths starting from 3
	for length := 3; length <= n; length++ {
		for i := 1; i <= n-length+1; i++ {
			j := i + length - 1
			if length == 3 {
				dp[i][j] = i * (i+1) * j
			} else {
				minVal := 1<<63 - 1
				for k := i + 1; k < j; k++ {
					current := dp[i][k] + dp[k][j] + i*k*j
					if current < minVal {
						minVal = current
					}
				}
				dp[i][j] = minVal
			}
		}
	}

	fmt.Fprintln(writer, dp[1][n])
}
